#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <mpfr.h>

typedef struct { mpfr_t lo, hi; } iv;
static mpfr_prec_t PREC=80;
static mpfr_t tmpv[16];
static void init(iv*x){mpfr_init2(x->lo,PREC);mpfr_init2(x->hi,PREC);}
static void zero(iv*x){mpfr_set_ui(x->lo,0,MPFR_RNDD);mpfr_set_ui(x->hi,0,MPFR_RNDU);}
static void ui(iv*x,unsigned long n){mpfr_set_ui(x->lo,n,MPFR_RNDD);mpfr_set_ui(x->hi,n,MPFR_RNDU);}
static void cp(iv*o,const iv*a){mpfr_set(o->lo,a->lo,MPFR_RNDD);mpfr_set(o->hi,a->hi,MPFR_RNDU);}
static void add(iv*o,const iv*a,const iv*b){mpfr_add(o->lo,a->lo,b->lo,MPFR_RNDD);mpfr_add(o->hi,a->hi,b->hi,MPFR_RNDU);}
static void subui(iv*o,const iv*a,unsigned long n){mpfr_set_ui(tmpv[8],n,MPFR_RNDN);mpfr_sub(o->lo,a->lo,tmpv[8],MPFR_RNDD);mpfr_sub(o->hi,a->hi,tmpv[8],MPFR_RNDU);}
static void oneminus(iv*o,const iv*a){mpfr_set_ui(tmpv[8],1,MPFR_RNDN);mpfr_sub(o->lo,tmpv[8],a->hi,MPFR_RNDD);mpfr_sub(o->hi,tmpv[8],a->lo,MPFR_RNDU);}
static void mului(iv*o,const iv*a,unsigned long n){mpfr_mul_ui(o->lo,a->lo,n,MPFR_RNDD);mpfr_mul_ui(o->hi,a->hi,n,MPFR_RNDU);}
static void mul(iv*o,const iv*a,const iv*b){
 mpfr_mul(tmpv[0],a->lo,b->lo,MPFR_RNDD);mpfr_mul(tmpv[1],a->lo,b->hi,MPFR_RNDD);mpfr_mul(tmpv[2],a->hi,b->lo,MPFR_RNDD);mpfr_mul(tmpv[3],a->hi,b->hi,MPFR_RNDD);int mi=0;for(int i=1;i<4;i++)if(mpfr_cmp(tmpv[i],tmpv[mi])<0)mi=i;mpfr_set(o->lo,tmpv[mi],MPFR_RNDD);
 mpfr_mul(tmpv[4],a->lo,b->lo,MPFR_RNDU);mpfr_mul(tmpv[5],a->lo,b->hi,MPFR_RNDU);mpfr_mul(tmpv[6],a->hi,b->lo,MPFR_RNDU);mpfr_mul(tmpv[7],a->hi,b->hi,MPFR_RNDU);int ma=4;for(int i=5;i<8;i++)if(mpfr_cmp(tmpv[i],tmpv[ma])>0)ma=i;mpfr_set(o->hi,tmpv[ma],MPFR_RNDU);
}
static void diviv(iv*o,const iv*a,const iv*b){if(mpfr_cmp_si(b->lo,0)<=0){fprintf(stderr,"nonpositive divisor\n");exit(2);}mpfr_div(tmpv[0],a->lo,b->lo,MPFR_RNDD);mpfr_div(tmpv[1],a->lo,b->hi,MPFR_RNDD);mpfr_div(tmpv[2],a->hi,b->lo,MPFR_RNDD);mpfr_div(tmpv[3],a->hi,b->hi,MPFR_RNDD);int mi=0;for(int i=1;i<4;i++)if(mpfr_cmp(tmpv[i],tmpv[mi])<0)mi=i;mpfr_set(o->lo,tmpv[mi],MPFR_RNDD);mpfr_div(tmpv[4],a->lo,b->lo,MPFR_RNDU);mpfr_div(tmpv[5],a->lo,b->hi,MPFR_RNDU);mpfr_div(tmpv[6],a->hi,b->lo,MPFR_RNDU);mpfr_div(tmpv[7],a->hi,b->hi,MPFR_RNDU);int ma=4;for(int i=5;i<8;i++)if(mpfr_cmp(tmpv[i],tmpv[ma])>0)ma=i;mpfr_set(o->hi,tmpv[ma],MPFR_RNDU);}
static void logiv(iv*o,const iv*a){mpfr_log(o->lo,a->lo,MPFR_RNDD);mpfr_log(o->hi,a->hi,MPFR_RNDU);}
static void sqrtiv(iv*o,const iv*a){mpfr_sqrt(o->lo,a->lo,MPFR_RNDD);mpfr_sqrt(o->hi,a->hi,MPFR_RNDU);}
static void sincosiv(iv*s,iv*c,const iv*x){mpfr_add(tmpv[8],x->lo,x->hi,MPFR_RNDN);mpfr_div_2ui(tmpv[8],tmpv[8],1,MPFR_RNDN);mpfr_sub(tmpv[9],tmpv[8],x->lo,MPFR_RNDU);mpfr_sub(tmpv[14],x->hi,tmpv[8],MPFR_RNDU);if(mpfr_cmp(tmpv[14],tmpv[9])>0)mpfr_set(tmpv[9],tmpv[14],MPFR_RNDU);mpfr_sin(tmpv[10],tmpv[8],MPFR_RNDD);mpfr_sub(s->lo,tmpv[10],tmpv[9],MPFR_RNDD);mpfr_sin(tmpv[11],tmpv[8],MPFR_RNDU);mpfr_add(s->hi,tmpv[11],tmpv[9],MPFR_RNDU);mpfr_cos(tmpv[12],tmpv[8],MPFR_RNDD);mpfr_sub(c->lo,tmpv[12],tmpv[9],MPFR_RNDD);mpfr_cos(tmpv[13],tmpv[8],MPFR_RNDU);mpfr_add(c->hi,tmpv[13],tmpv[9],MPFR_RNDU);if(mpfr_cmp_si(s->lo,-1)<0)mpfr_set_si(s->lo,-1,MPFR_RNDD);if(mpfr_cmp_si(s->hi,1)>0)mpfr_set_si(s->hi,1,MPFR_RNDU);if(mpfr_cmp_si(c->lo,-1)<0)mpfr_set_si(c->lo,-1,MPFR_RNDD);if(mpfr_cmp_si(c->hi,1)>0)mpfr_set_si(c->hi,1,MPFR_RNDU);}
static uint64_t* simple(uint64_t n,size_t*out){uint8_t*m=malloc(n+1);if(!m)exit(2);memset(m,1,n+1);m[0]=0;if(n>=1)m[1]=0;for(uint64_t p=2;p*p<=n;p++)if(m[p])for(uint64_t q=p*p;q<=n;q+=p)m[q]=0;size_t k=0;for(uint64_t p=2;p<=n;p++)if(m[p])k++;uint64_t*a=malloc(k*sizeof(uint64_t));if(!a)exit(2);size_t j=0;for(uint64_t p=2;p<=n;p++)if(m[p])a[j++]=p;free(m);*out=k;return a;}
static uint64_t* segment(uint64_t lo,uint64_t hi,const uint64_t*base,size_t nb,size_t*out){size_t len=hi-lo;uint8_t*m=malloc(len);if(!m){fprintf(stderr,"segment allocation failed: %zu\n",len);exit(2);}memset(m,1,len);uint64_t root=sqrtl(hi-1);while((root+1)*(root+1)<=hi-1)root++;while(root*root>hi-1)root--;for(size_t i=0;i<nb;i++){uint64_t p=base[i];if(p>root)break;uint64_t st=p*p,mm=((lo+p-1)/p)*p;if(mm>st)st=mm;if(st<hi)for(uint64_t q=st;q<hi;q+=p)m[q-lo]=0;}size_t k=0;for(size_t i=0;i<len;i++)if(m[i]&&lo+i>=2)k++;uint64_t*a=malloc(k*sizeof(uint64_t));if(!a)exit(2);size_t j=0;for(size_t i=0;i<len;i++)if(m[i]&&lo+i>=2)a[j++]=lo+i;free(m);*out=k;return a;}

int main(int argc,char**argv){if(argc<10){fprintf(stderr,"usage: %s cutoff carrier cells segment_size start end include_higher output precision\n",argv[0]);return 2;}uint64_t C=strtoull(argv[1],0,10);const char*Tstr=argv[2];int K=atoi(argv[3]);uint64_t segsize=strtoull(argv[4],0,10),s0=strtoull(argv[5],0,10),s1=strtoull(argv[6],0,10);int hp=atoi(argv[7]);const char*outpath=argv[8];PREC=atol(argv[9]);uint64_t nseg=(C-2)/segsize+1;if(!(s0<s1&&s1<=nseg))return 2;for(int i=0;i<16;i++)mpfr_init2(tmpv[i],PREC);
 iv *zr=calloc(K,sizeof(iv)),*zi=calloc(K,sizeof(iv));for(int d=0;d<K;d++){init(&zr[d]);init(&zi[d]);zero(&zr[d]);zero(&zi[d]);}
 iv pi,civ,logc,Tiv,piv,qiv,logp,logq,sqrtq,den,w,r,f,omf,phase,sinv,cosv,zre,zim,t1,tmp;iv*all[]={&pi,&civ,&logc,&Tiv,&piv,&qiv,&logp,&logq,&sqrtq,&den,&w,&r,&f,&omf,&phase,&sinv,&cosv,&zre,&zim,&t1,&tmp};for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)init(all[i]);mpfr_const_pi(pi.lo,MPFR_RNDD);mpfr_const_pi(pi.hi,MPFR_RNDU);ui(&civ,C);logiv(&logc,&civ);if(mpfr_set_str(Tiv.lo,Tstr,10,MPFR_RNDD)||mpfr_set_str(Tiv.hi,Tstr,10,MPFR_RNDU))return 2;
 uint64_t root=sqrtl(C);while((root+1)*(root+1)<=C)root++;while(root*root>C)root--;size_t nb=0;uint64_t*base=simple(root,&nb);uint64_t pc=0,hc=0,tot=0;long amb=0;time_t started=time(0);
#define TERM(P,Q,E,H) do{uint64_t _p=(P),_q=(Q);unsigned _e=(E);tot++;if(H)hc++;ui(&piv,_p);logiv(&logp,&piv);ui(&qiv,_q);sqrtiv(&sqrtq,&qiv);mul(&den,&pi,&sqrtq);diviv(&w,&logp,&den);mului(&logq,&logp,_e);mului(&tmp,&logq,(unsigned long)K);diviv(&r,&tmp,&logc);long nl=mpfr_get_si(r.lo,MPFR_RNDD),nh=mpfr_get_si(r.hi,MPFR_RNDD);if(nl!=nh){amb++;fprintf(stderr,"ambiguous q=%llu\n",(unsigned long long)_q);return 3;}long n=nl;if(n>=0&&n<K){subui(&f,&r,(unsigned long)n);oneminus(&omf,&f);mul(&phase,&Tiv,&logq);sincosiv(&sinv,&cosv,&phase);mul(&zre,&w,&cosv);mul(&t1,&w,&sinv);mpfr_neg(zim.lo,t1.hi,MPFR_RNDD);mpfr_neg(zim.hi,t1.lo,MPFR_RNDU);mul(&t1,&omf,&zre);add(&tmp,&zr[n],&t1);cp(&zr[n],&tmp);mul(&t1,&omf,&zim);add(&tmp,&zi[n],&t1);cp(&zi[n],&tmp);if(n+1<K){mul(&t1,&f,&zre);add(&tmp,&zr[n+1],&t1);cp(&zr[n+1],&tmp);mul(&t1,&f,&zim);add(&tmp,&zi[n+1],&t1);cp(&zi[n+1],&tmp);}}}while(0)
 for(uint64_t s=s0;s<s1;s++){uint64_t lo=2+s*segsize,hi=lo+segsize;if(hi>C+1||hi<lo)hi=C+1;size_t np=0;uint64_t*ps=segment(lo,hi,base,nb,&np);for(size_t i=0;i<np;i++){uint64_t p=ps[i];TERM(p,p,1,0);pc++;}free(ps);fprintf(stderr,"segment=%llu primes=%llu terms=%llu elapsed=%ld\n",(unsigned long long)s,(unsigned long long)pc,(unsigned long long)tot,(long)(time(0)-started));}
 if(hp)for(size_t i=0;i<nb;i++){uint64_t p=base[i],q=p*p;unsigned e=2;while(q<=C){TERM(p,q,e,1);if(q>C/p)break;q*=p;e++;}}
 FILE*out=fopen(outpath,"w");if(!out)return 2;fprintf(out,"{\n\"schema\":\"riemann.mpfr-toeplitz-box-shard.v1\",\n\"cutoff\":%llu,\n\"carrier\":\"%s\",\n\"cells\":%d,\n\"precision_bits\":%ld,\n\"segment_size\":%llu,\n\"total_segments\":%llu,\n\"segment_start\":%llu,\n\"segment_end\":%llu,\n\"include_higher_powers\":%s,\n\"prime_count\":%llu,\n\"higher_prime_power_count\":%llu,\n\"total_terms\":%llu,\n\"ambiguous_lags\":%ld,\n\"lags\":[\n",(unsigned long long)C,Tstr,K,(long)PREC,(unsigned long long)segsize,(unsigned long long)nseg,(unsigned long long)s0,(unsigned long long)s1,hp?"true":"false",(unsigned long long)pc,(unsigned long long)hc,(unsigned long long)tot,amb);
 for(int d=0;d<K;d++){double rl=mpfr_get_d(zr[d].lo,MPFR_RNDD),rh=mpfr_get_d(zr[d].hi,MPFR_RNDU),il=mpfr_get_d(zi[d].lo,MPFR_RNDD),ih=mpfr_get_d(zi[d].hi,MPFR_RNDU);fprintf(out,"{\"lag\":%d,\"real_lower_hex\":\"%a\",\"real_upper_hex\":\"%a\",\"imag_lower_hex\":\"%a\",\"imag_upper_hex\":\"%a\"}%s\n",d,rl,rh,il,ih,d+1<K?",":"");}
 fprintf(out,"]\n}\n");fclose(out);fprintf(stderr,"done prime=%llu higher=%llu total=%llu ambiguous=%ld elapsed=%ld\n",(unsigned long long)pc,(unsigned long long)hc,(unsigned long long)tot,amb,(long)(time(0)-started));return 0;}
